<?php
declare(strict_types=1);
// View-only current-state checks: no database or account writes.
require __DIR__ . '/../app/autoload.php';
$checks = 0;
$assert = static function (bool $ok, string $message) use (&$checks): void {
    if (!$ok) throw new RuntimeException($message);
    ++$checks;
};
$render = static function (array $data = []): string {
    $basePath = '/EcoLot-LK';
    $profile = ['company_name'=>'Owner <Recovery>','full_name'=>'Owner "Contact"','email'=>'owner@example.org','mobile_number'=>'94770000000','business_address'=>'Recorded & private','district'=>'Colombo'];
    $compliance = ['verification_status'=>'VERIFIED'];
    $capabilities = [['category_name'=>'Owner <Category>','capability_status'=>'APPROVED','can_handle_high_risk'=>0],['category_name'=>'Pending category','capability_status'=>'PENDING','can_handle_high_risk'=>1,'review_note'=>'Evidence <required>'],['category_name'=>'Rejected category','capability_status'=>'REJECTED','can_handle_high_risk'=>1]];
    $activities = [['activity_type'=>'RECYCLING','activity_status'=>'APPROVED'],['activity_type'=>'DISPOSAL','activity_status'=>'REJECTED','review_note'=>'Not supported'],['activity_type'=>'STORAGE','activity_status'=>'PENDING']];
    $license = ['license_no'=>'OWNER-CEA-001','license_expiry'=>'2099-02-01','license_status'=>'VALID'];
    $licenseValid = true;
    $documentAvailable = true;
    $scopeAvailable = true;
    $scopes = [];
    extract($data, EXTR_OVERWRITE);
    ob_start(); require APP_ROOT . '/app/Views/recycler/profile.php'; return ob_get_clean();
};
$html = $render();
foreach (['Owner &lt;Recovery&gt;','Owner &quot;Contact&quot;','Recorded &amp; private','Owner &lt;Category&gt;','2099-02-01','Awaiting review','Approved','Rejected','Pending','Requested — awaiting review','Not authorized','OWNER-CEA-001','No current verified scope','Evidence &lt;required&gt;','Not supported'] as $value) $assert(str_contains($html,$value),'Accurate escaped state: '.$value);
foreach (['data-profile-open','data-profile-template','data-profile-modal','<form','profile.js','Submit license Update','Request Capability Change'] as $fake) $assert(!str_contains($html,$fake),'No draft/mutation controls: '.$fake);
$dom = new DOMDocument(); @$dom->loadHTML($html); $x = new DOMXPath($dom);
$assert($x->query('//a[contains(@href,"/recycler/profile/licence-document")]')->length===1,'Owner-only PDF route offered');
$assert($x->query('//input|//textarea|//select')->length===0,'Sensitive identity is read-only');
$assert($x->query('//details/summary[contains(.,"Review feedback")]')->length===2,'Review notes secondary');
$assert(str_contains($render(['licenseValid'=>false]),'>Expired<'),'Expired valid record is not shown as current valid');
$assert(!str_contains($render(['documentAvailable'=>false]),'href="/EcoLot-LK/recycler/profile/licence-document"'),'Unavailable document has no dead action');
$scope=['category_name'=>'Domestic','activity_type'=>'RECYCLING','scope_status'=>'VERIFIED','current_document'=>false,'covers_high_risk'=>1,'authorization_basis'=>'SWML','waste_description'=>'Documented devices','evidence_reference'=>'Page 2','licence_conditions'=>'Conditions apply'];
$historical=$render(['scopes'=>[$scope]]);
$assert(str_contains($historical,'No current verified scope')&&str_contains($historical,'Historical or unavailable document'),'Historical evidence is not current coverage');
$scope['current_document']=true;
$assert(str_contains($render(['scopes'=>[$scope]]),'Verified coverage recorded'),'Current verified evidence displayed independently');
$scope['scope_status']='PENDING';
$assert(str_contains($render(['scopes'=>[$scope]]),'No current verified scope'),'Pending scope grants no coverage');
$assert(str_contains($render(['scopeAvailable'=>false]),'>Unavailable<'),'Missing storage has honest unavailable state');
$empty=$render(['profile'=>null,'compliance'=>null,'license'=>null,'capabilities'=>[],'activities'=>[]]);
foreach (['Not recorded','No licence has been submitted.','No handling capabilities are recorded.','No activities are recorded.'] as $text) $assert(str_contains($empty,$text),'Empty state: '.$text);
$assert(str_contains($render(['license'=>null]),'No approved licence is selected.'),'Legacy unselected approval is not described as an absent submission');
$editable=['editable'=>true,'phone_available'=>true,'pending'=>null,'other_session'=>false];
$contact=$render(['editState'=>$editable,'edit'=>'contact','csrf'=>'test-token']);
$assert(str_contains($contact,'name="contact_person"') && str_contains($contact,'name="_csrf_token"'),'Contact editor has CSRF and name');
foreach(['company_name','email','business_address','district'] as $field)$assert(!str_contains($contact,'name="'.$field.'"'),'Company field stays read-only: '.$field);
$phone=$render(['editState'=>$editable,'edit'=>'phone','csrf'=>'test-token']);
$assert(str_contains($phone,'type="password"')&&str_contains($phone,'name="mobile_number"'),'Phone requires current password and proposed mobile');
$assert(!str_contains($phone,'name="otp"'),'No unissued verification form');
$editable['pending']=['masked_mobile'=>'9477••••123','expires_at'=>'2099-01-01 12:00:00','sent'=>true];
$verify=$render(['editState'=>$editable,'edit'=>'phone','csrf'=>'test-token']);
foreach(['name="otp"','/phone/verify','/phone/resend','/phone/cancel','9477••••123'] as $value)$assert(str_contains($verify,$value),'Pending verification control: '.$value);
$assert(!str_contains($verify,'type="password"'),'Pending form does not retain password');
$assert(!str_contains($render(['editState'=>array_replace($editable,['editable'=>false]),'edit'=>'phone']),'<form'),'Suspended account has no edit controls');
$renewal=$render(['editState'=>['editable'=>true,'phone_available'=>true,'pending'=>null,'other_session'=>false],'renewalAvailable'=>true,'edit'=>'licence','csrf'=>'safe-token']);
foreach(['Update CEA Licence','enctype="multipart/form-data"','name="licence_pdf"','name="license_number"','name="expiry_date"','name="explanation"','approved licence stays unchanged'] as $value)$assert(str_contains($renewal,$value),'Renewal form contract: '.$value);
$assert(!str_contains($renewal,'name="contact_person"')&&!str_contains($renewal,'type="password"'),'Renewal form does not duplicate contact/phone editors');
$capForm=$render(['editState'=>['editable'=>true,'phone_available'=>true,'pending'=>null,'other_session'=>false],'capabilityAvailable'=>true,'capabilityCategories'=>[['category_id'=>99,'category_name'=>'New <category>']],'edit'=>'capability','csrf'=>'safe-token']);
foreach(['Request Capability Change','name="category_id"','name="request_type"','name="requested_can_handle_high_risk"','name="request_reason"','value="ADD"','value="UPDATE"','value="DEACTIVATE"','New &lt;category&gt;','permissions stay unchanged'] as $value)$assert(str_contains($capForm,$value),'Capability editor contract: '.$value);
$assert(!str_contains($capForm,'name="activity_type"')&&!str_contains($capForm,'enctype="multipart/form-data"'),'Capability editor cannot alter activities or licence documents');
echo "PASS: $checks Profile current-state / permissions / escaping assertions (no database access)\n";
